"""Disk cache for structured LLM results: code/.cache/llm/<sha256>.json (gitignored)."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

DEFAULT_CACHE_DIR = Path(__file__).resolve().parents[2] / ".cache" / "llm"


